args <- commandArgs(trailingOnly=TRUE); hit <- grep("^--config=",args); if (!length(hit)) stop("Use --config=path/to/preprocessing.yml"); cfg_path <- sub("^--config=","",args[hit[1]]); if (!file.exists(cfg_path)) stop("Configuration file not found: ",cfg_path); root <- normalizePath(file.path(dirname(cfg_path),".."),mustWork=TRUE); files <- c("preprocessing_config.R","preprocessing_validation.R","preprocessing_observations.R","preprocessing_spatial.R","preprocessing_covariates.R","preprocessing_transformations.R","preprocessing_outputs.R"); for (f in files) source(file.path(root,"R",f)); cfg <- read_preprocessing_config(cfg_path,root); validate_preprocessing_config(cfg); dir.create(cfg$project$output_directory,recursive=TRUE,showWarnings=FALSE); boundary <- sf::st_read(cfg$inputs$study_boundary,quiet=TRUE); cleaned <- preprocess_observations(read_observations(cfg$inputs$observations),boundary,cfg,read_host_lookup(file.path(root,"config/host_lookup.csv"))); support <- build_spatial_support(boundary,cleaned$data,cfg); time <- make_week_index(cfg$study$start_date,cfg$study$end_date); t1 <- build_tier1(cleaned$data,support$integration_points,time); t2 <- build_tier2(cleaned$data,support,time); pred <- build_prediction_grid(support,time); out <- assemble_model_inputs(t1,t2,pred,support,time,NULL,list(observation=cleaned$audit,covariate=data.frame()),cfg); saveRDS(out,file.path(cfg$project$output_directory,cfg$outputs$model_inputs)); write.csv(cleaned$audit,file.path(cfg$project$output_directory,cfg$outputs$observation_audit),row.names=FALSE); write.csv(data.frame(),file.path(cfg$project$output_directory,cfg$outputs$covariate_audit),row.names=FALSE); write.csv(cleaned$data[0,],file.path(cfg$project$output_directory,cfg$outputs$excluded_observations),row.names=FALSE)
